from collections import Counter


def transform(grid):
    """Restore rectangles/shapes by erasing scattered noise and filling holes.

    The demos show large non-background color regions as the intended objects;
    isolated marker cells outside them revert to the dominant background. Within
    a near-solid component's bounding box, cells are restored to its color.
    """
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append((color, comp))

    out = [row[:] for row in grid]
    footprints = []
    for color, comp in components:
        if len(comp) < 4:
            continue
        r0 = min(r for r, c in comp)
        r1 = max(r for r, c in comp)
        c0 = min(c for r, c in comp)
        c1 = max(c for r, c in comp)
        area = (r1-r0+1) * (c1-c0+1)
        if area <= len(comp) * 1.5:
            footprints.append((color, r0, r1, c0, c1))
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    out[r][c] = color

    large_cells = {p for color, comp in components if len(comp) >= 4 for p in comp}
    for color, comp in components:
        if len(comp) == 1 and comp[0] not in large_cells:
            r, c = comp[0]
            out[r][c] = bg
    return out


